-- ============================================================
-- 吞噬.lua —— 吃糖小怪兽序列帧像素动画（60x60，融合等待投喂姿态·方案B）
-- 数据来源：用户上传 GIF 序列帧（透明背景）与等待投喂 PNG（透明背景）。
-- 第 1 帧：等待投喂姿态（方案 B·交集对齐）。等待投喂 PNG 复现 60x60 网格后，等比 contain 缩放并居中到吞噬动画各帧稳定身体交集区域
--           x[5,50] y[1,53]（46x53），颜色映射回本调色板；喂糖时第 1 帧切到第 2-6 帧身体无跳变。
-- 第 2-6 帧：原吞噬动画，FRAME_MS=40 循环播放。
-- 格式：GRID=60，PALETTE，FRAMES。配合 objectUI.createPixelSequence / createPixelObject 使用。
-- ============================================================

